package aetherdir

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// semanticColorKeys are the named color roles shared by every Waifer export.
var semanticColorKeys = []string{"background", "foreground", "accent", "cursor"}

// paletteColorKeys returns color0 through color15 in numeric order.
func paletteColorKeys() []string {
	keys := make([]string, 0, 16)
	for i := 0; i < 16; i++ {
		keys = append(keys, fmt.Sprintf("color%d", i))
	}
	return keys
}

// writeCurrentExport writes one generated file into CurrentDir(). Every export
// re-runs Ensure() so callers can invoke any writer independently on a fresh install.
func writeCurrentExport(name, content string) error {
	if err := Ensure(); err != nil {
		return err
	}
	path := filepath.Join(CurrentDir(), name)
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		return fmt.Errorf("write %s: %w", name, err)
	}
	return nil
}

// WriteThemeCSS writes theme.css: CSS custom properties for the semantic roles,
// the 16 ANSI colors, and cursor when supplied.
func WriteThemeCSS(vars map[string]string) error {
	var b strings.Builder
	b.WriteString("/* Generated by Waifer. Do not edit - changes will be overwritten. */\n")
	b.WriteString(":root {\n")
	for _, role := range []struct{ key, css string }{
		{"background", "bg"},
		{"foreground", "fg"},
		{"accent", "accent"},
	} {
		fmt.Fprintf(&b, "  --%s: %s;\n", role.css, vars[role.key])
	}
	if cursor := vars["cursor"]; cursor != "" {
		fmt.Fprintf(&b, "  --cursor: %s;\n", cursor)
	}
	for _, key := range paletteColorKeys() {
		fmt.Fprintf(&b, "  --%s: %s;\n", key, vars[key])
	}
	b.WriteString("}\n")
	return writeCurrentExport("theme.css", b.String())
}

// WriteThemeJSON writes theme.json with the semantic color roles and a colors
// object keyed color0..color15.
func WriteThemeJSON(vars map[string]string) error {
	var b strings.Builder
	b.WriteString("{\n")
	for _, key := range semanticColorKeys {
		fmt.Fprintf(&b, "  %s: %s,\n", strconv.Quote(key), strconv.Quote(vars[key]))
	}
	b.WriteString("  \"colors\": {\n")
	palette := paletteColorKeys()
	for i, key := range palette {
		fmt.Fprintf(&b, "    %s: %s", strconv.Quote(key), strconv.Quote(vars[key]))
		if i < len(palette)-1 {
			b.WriteByte(',')
		}
		b.WriteByte('\n')
	}
	b.WriteString("  }\n}\n")
	return writeCurrentExport("theme.json", b.String())
}

// WriteColorsINI writes colors.ini with a [Colors] section for Rainmeter, AHK,
// Flow Launcher and similar INI-based consumers.
func WriteColorsINI(vars map[string]string) error {
	var b strings.Builder
	b.WriteString("; Generated by Waifer. Do not edit - changes will be overwritten.\n")
	b.WriteString("[Colors]\n")
	for _, key := range semanticColorKeys {
		fmt.Fprintf(&b, "%s=%s\n", key, vars[key])
	}
	for _, key := range paletteColorKeys() {
		fmt.Fprintf(&b, "%s=%s\n", key, vars[key])
	}
	return writeCurrentExport("colors.ini", b.String())
}

// WriteColorsPS1 writes colors.ps1, a PowerShell hashtable named $WaiferColors.
func WriteColorsPS1(vars map[string]string) error {
	var b strings.Builder
	b.WriteString("# Generated by Waifer. Do not edit - changes will be overwritten.\n")
	b.WriteString("$WaiferColors = @{\n")
	for _, key := range semanticColorKeys {
		fmt.Fprintf(&b, "    %s = '%s';\n", key, strings.ReplaceAll(vars[key], "'", "''"))
	}
	for _, key := range paletteColorKeys() {
		fmt.Fprintf(&b, "    %s = '%s';\n", key, strings.ReplaceAll(vars[key], "'", "''"))
	}
	b.WriteString("}\n")
	return writeCurrentExport("colors.ps1", b.String())
}

// WriteLiveExports writes every standardized live export into CurrentDir().
// All writers are attempted even if one fails; the first error is returned as a
// diagnostic so a single bad export never prevents the remaining files from
// being refreshed. Wallpaper copying and hook execution remain caller-owned.
func WriteLiveExports(vars map[string]string) error {
	if err := Ensure(); err != nil {
		return err
	}

	themeName := vars["theme_name"]
	if themeName == "" {
		themeName = vars["name"]
	}
	exports := []struct {
		name  string
		write func() error
	}{
		{"theme.css", func() error { return WriteThemeCSS(vars) }},
		{"theme.json", func() error { return WriteThemeJSON(vars) }},
		{"colors.ini", func() error { return WriteColorsINI(vars) }},
		{"colors.ps1", func() error { return WriteColorsPS1(vars) }},
		{"colors.toml", func() error { return WriteColorsToml(vars) }},
		{"theme.md", func() error { return WriteThemeMeta(vars, themeName) }},
	}

	var firstErr error
	for _, export := range exports {
		if err := export.write(); err != nil {
			fmt.Fprintf(os.Stderr, "waifer: live export %s failed: %v\n", export.name, err)
			if firstErr == nil {
				firstErr = fmt.Errorf("live export %s: %w", export.name, err)
			}
		}
	}
	return firstErr
}
